def min_window_subsequence(s1, s2):
    """Find shortest substring of s1 containing s2 as subsequence."""
    m, n = len(s1), len(s2)
    if n == 0:
        return ""

    dp = [-1] * n
    result = ""
    min_len = float('inf')

    for i in range(m):
        # Iterate backwards to avoid overwriting dp[j-1] before using it
        for j in range(n - 1, -1, -1):
            if s1[i] == s2[j]:
                if j == 0:
                    dp[j] = i  # Start new window
                else:
                    dp[j] = dp[j - 1]  # Inherit previous start

        # Check if we have a complete match
        if dp[n - 1] != -1:
            start = dp[n - 1]
            length = i - start + 1
            if length < min_len:
                min_len = length
                result = s1[start:i + 1]

    return result
